namespace SparkFlow.Server.Application.Features.Workers.RegisterWorker; public sealed class RegisterWorkerValidator { public bool Validate(RegisterWorkerCommand command, out string? error){ if(string.IsNullOrWhiteSpace(command.Name)){ error="Worker name is required."; return false;} if(string.IsNullOrWhiteSpace(command.MachineId)){ error="MachineId is required."; return false;} error=null; return true; } }
